const footer = {
  id:'footer',
  copy:{
    copyright: <>&#169;&nbsp;Old Mates Cranes & Rigging</>,
    byCopy: 'carlosesierra.com.au',
    byUrl: 'https://carlosesierra.com.au/'
  }
};

const Footer = () =>  (
    <section className='container-fluid p-0 bg-charcoal' id={footer.id}>
      <div className='row px-4 g-0'>
        <div className='col text-white fs-6'>
          {footer.copy.copyright}– <a href={footer.copy.byUrl} className='text-white '>web design</a> by
          {footer.copy.byCopy}
        </div>
      </div>
    </section>
)

export default Footer;
